// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(address nonCreator, uint256 depositAmount) public {
        vm.assume(nonCreator != address(this) && nonCreator != address(0));
        vm.assume(depositAmount > 0);

        vm.deal(nonCreator, depositAmount);
        vm.prank(nonCreator);
        c.deposit{value: depositAmount}();

        uint256 contractBalanceBefore = address(c).balance;

        vm.prank(nonCreator);
        bool success;
        try c.migrateTo(nonCreator) { success = true; } catch { success = false; }

        uint256 nonCreatorBalanceAfter = nonCreator.balance;
        uint256 contractBalanceAfter = address(c).balance;

        assertTrue(!success);
    }
}
